import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"@svta/cml-608 changelog","description":"","frontmatter":{},"headers":[],"relativePath":"packages/608/changelog.md","filePath":"packages/608/changelog.md"}`),a={name:`packages/608/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="svta-cml-608-changelog" tabindex="-1">@svta/cml-608 changelog <a class="header-anchor" href="#svta-cml-608-changelog" aria-label="Permalink to “@svta/cml-608 changelog”">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.1.1...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>PenState.foreground</code> is <code>string | null</code>, the type of <code>PenStyles.foreground</code>. A PAC without a color already set it to <code>null</code>. TypeScript consumers that read <code>foreground</code> as a <code>string</code> need to handle <code>null</code>. <code>setStyles</code> assigns the five styles directly, with no allocation per call. A style key that is present with the value <code>undefined</code> keeps the previous value instead of storing <code>undefined</code>.</li><li><code>SccParser</code> types its <code>processor</code> as <code>Pick&lt;Cta608Parser, &#39;addData&#39;&gt;</code> and its <code>field</code> as <code>number</code>. Both were <code>any</code>.</li><li>The README now has a When to use section. The section names the tasks that the package covers and the entry point of each task.</li></ul><h2 id="_1-1-1-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.1.0...608-v1.1.1" target="_blank" rel="noreferrer">1.1.1</a> - 2026-10-18 <a class="header-anchor" href="#_1-1-1-2026-10-18" aria-label="Permalink to “1.1.1 - 2026-10-18”">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>@svta/cml-utils</code> is now a declared peer dependency with the range <code>^1.6.2</code>.</li><li>README: the prose is rewritten for readers who do not read English as a first language. The extractor table and the code examples are unchanged.</li><li>README: the extraction example is complete. The sample inputs are function parameters.</li></ul><h2 id="_1-1-0-2026-08-13" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.0.3...608-v1.1.0" target="_blank" rel="noreferrer">1.1.0</a> - 2026-08-13 <a class="header-anchor" href="#_1-1-0-2026-08-13" aria-label="Permalink to “1.1.0 - 2026-08-13”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>extractCta608DataFromAv1Sample</code> extracts CTA-608 field data from AV1 (<code>av01</code>) samples, where captions are carried in a <code>metadata_itu_t_t35</code> OBU rather than in an SEI message. The <code>cc_data()</code> payload is identical to the SEI path, so the result feeds <code>Cta608Parser</code> unchanged. Select on the sample entry type: NAL unit and AV1 samples are framed differently and neither is self-identifying, so the framing has to come from the sample entry rather than from the bytes.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The <code>cc_data()</code> parser is now shared by the SEI and OBU carriage paths, and every caller bounds it by the structure that encloses it — the SEI message, the OBU payload, or the range handed to <code>extractCta608Data</code> — rather than trusting <code>cc_count</code> alone. No change to extracted data for well-formed input.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A wrong <code>cc_count</code> no longer reads caption pairs out of the bytes following the payload it belongs to, which in a multi-message SEI NAL could turn the header of the next message into a caption pair.</li><li>A <code>user_data_registered_itu_t_t35</code> payload carrying only the 8-byte A/53 identifier no longer throws a <code>RangeError</code> when <code>cc_data()</code> would start past the end of the buffer.</li></ul><h2 id="_1-0-3-2026-07-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.0.2...608-v1.0.3" target="_blank" rel="noreferrer">1.0.3</a> - 2026-07-22 <a class="header-anchor" href="#_1-0-3-2026-07-22" aria-label="Permalink to “1.0.3 - 2026-07-22”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A CTA-608 mid-row style code now advances the cursor by one column. A mid-row code is a spacing attribute: it occupies one on-screen cell (a space carrying the new pen) and advances the cursor, so following text starts one column to the right. Previously <code>ccMIDROW</code> only set the pen and did not advance the cursor, so colored/italic text was rendered one column too far left. (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/391" target="_blank" rel="noreferrer">#391</a>)</li></ul><h2 id="_1-0-2-2026-02-13" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.0.1...608-v1.0.2" target="_blank" rel="noreferrer">1.0.2</a> - 2026-02-13 <a class="header-anchor" href="#_1-0-2-2026-02-13" aria-label="Permalink to “1.0.2 - 2026-02-13”">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>CEA608 parser now supports H.265 (HEVC) and H.266 (VVC) SEI NALU types in addition to H.264 (AVC). This fixes CEA608 parsing in H.265/H.266 streams.</li></ul><h2 id="_1-0-1-2025-12-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/608-v1.0.0...608-v1.0.1" target="_blank" rel="noreferrer">1.0.1</a> - 2025-12-22 <a class="header-anchor" href="#_1-0-1-2025-12-22" aria-label="Permalink to “1.0.1 - 2025-12-22”">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The <code>extractCta608DataFromSample</code> function is missing from <code>@svta/cml-608</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/276" target="_blank" rel="noreferrer">#276</a>)</li><li>Use fixed version numbers for all CML peer dependencies (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/277" target="_blank" rel="noreferrer">#277</a>)</li></ul><h2 id="_1-0-0-2025-10-24" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/tree/608-v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2025-10-24 <a class="header-anchor" href="#_1-0-0-2025-10-24" aria-label="Permalink to “1.0.0 - 2025-10-24”">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Remove CommonJS exports (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/192" target="_blank" rel="noreferrer">#192</a>)</li><li>Convert to mono-repo (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/238" target="_blank" rel="noreferrer">#238</a>)</li><li>Produce single bundled export for each package (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/260" target="_blank" rel="noreferrer">#260</a>)</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};